// ============================================================
// PATCH v1.3.2: «Проверка → Гипотезы → Задания».
// Черновик дерева — плоский массив window.__trkHypDraft:
//   {id, kind:'hypothesis'|'task', parent, no, title, description,
//    date_from, date_to, status, assignees[]}
// Сохраняется ВСЁ дерево при каждом «💾 Сохранить» задачи
// (устаревший draft-экран v1.3.1 отключён ниже).
// Выбор сотрудников — чекбоксы из state.employees (надёжный
// источник), все кнопки type="button" + preventDefault.
// ============================================================
(function() {
    var DRAFT_KEY = '__trkHypDraft';
    function draft() {
        if (!Array.isArray(window[DRAFT_KEY])) window[DRAFT_KEY] = [];
        return window[DRAFT_KEY];
    }
    function setDraft(a) { window[DRAFT_KEY] = a; }
    function uid(p) {
        return p + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
    }
    function esc(s) {
        return String(s == null ? '' : s)
            .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
    }
    function empById(id) {
        var emps = (window.state && window.state.employees) || [];
        for (var i = 0; i < emps.length; i++) if (String(emps[i].id) === String(id)) return emps[i];
        return null;
    }
    function findItem(id) {
        var a = draft();
        for (var i = 0; i < a.length; i++) if (a[i].id === id) return a[i];
        return null;
    }
    function updField(id, key, val) {
        var it = findItem(id);
        if (it) it[key] = val;
    }
    function removeNode(id) {
        var a = draft();
        var kids = {};
        kids[id] = true;
        var changed = true;
        while (changed) {
            changed = false;
            for (var i = 0; i < a.length; i++) {
                if (kids[a[i].id]) continue;
                if (a[i].parent && kids[a[i].parent]) { kids[a[i].id] = true; changed = true; }
            }
        }
        setDraft(a.filter(function(x) { return !kids[x.id]; }));
        renumber();
        renderHypTree();
    }
    function renumber() {
        var a = draft(), n = 0;
        for (var i = 0; i < a.length; i++) if (a[i].kind === 'hypothesis') a[i].no = ++n;
    }
    function addHypothesis() {
        var a = draft().slice();
        a.push({ id: uid('h'), kind: 'hypothesis', parent: '', no: a.length + 1,
                 title: '', description: '', date_from: '', date_to: '',
                 status: 'planned', assignees: [] });
        setDraft(a); renumber(); renderHypTree();
    }
    function addTask(hypId) {
        var a = draft().slice();
        var pos = -1;
        for (var i = 0; i < a.length; i++) if (a[i].id === hypId) { pos = i; break; }
        if (pos === -1) return;
        var j = pos + 1;
        while (j < a.length && a[j].kind === 'task' && a[j].parent === hypId) j++;
        a.splice(j, 0, { id: uid('t'), kind: 'task', parent: hypId, no: 0,
                         title: '', description: '', date_from: '', date_to: '',
                         status: 'planned', assignees: [] });
        setDraft(a); renumber(); renderHypTree();
    }
    function peopleHtml(item) {
        var emps = (window.state && window.state.employees) || [];
        if (!emps.length) return '<div class="hyp-empty">Нет сотрудников — добавьте их в словаре</div>';
        var sel = item.assignees || [];
        var html = '<div class="hyp-people-list">';
        for (var i = 0; i < emps.length; i++) {
            var e = emps[i];
            var on = sel.indexOf(String(e.id)) !== -1 || sel.indexOf(e.id) !== -1;
            html += '<label class="hyp-person"><input type="checkbox" value="' + esc(e.id) + '"' + (on ? ' checked' : '') + '>'
                  + '<span class="hyp-dot" style="background:' + esc(e.color || '#888') + '"></span>'
                  + '<span>' + esc(e.name || '') + (e.fired ? ' 🚪' : '') + '</span></label>';
        }
        html += '</div>';
        return html;
    }
    function fieldsHtml(item, isTask) {
        return '<div class="hyp-fields">'
            + '<div class="hyp-row"><input type="text" class="hyp-fld" data-k="title" maxlength="200" placeholder="' + (isTask ? 'Название задания *' : 'Название гипотезы *') + '" value="' + esc(item.title) + '"></div>'
            + '<div class="hyp-row"><textarea class="hyp-fld" data-k="description" rows="2" maxlength="4000" placeholder="Описание">' + esc(item.description) + '</textarea></div>'
            + '<div class="hyp-row hyp-dates">'
            +   '<label>С <input type="date" class="hyp-fld" data-k="date_from" value="' + esc(item.date_from) + '"></label>'
            +   '<label>По <input type="date" class="hyp-fld" data-k="date_to" value="' + esc(item.date_to) + '"></label>'
            +   '<label>Статус <select class="hyp-fld" data-k="status">'
            +     '<option value="planned"' + (item.status === 'planned' ? ' selected' : '') + '>Планируется</option>'
            +     '<option value="in_progress"' + (item.status === 'in_progress' ? ' selected' : '') + '>В работе</option>'
            +     '<option value="done"' + (item.status === 'done' ? ' selected' : '') + '>Выполнено</option>'
            +     '<option value="failed"' + (item.status === 'failed' ? ' selected' : '') + '>Не подтверждено</option>'
            +   '</select></label>'
            + '</div>'
            + '<div class="hyp-people"><div class="hyp-people-label">👥 Ответственные:</div>' + peopleHtml(item) + '</div>'
            + '</div>';
    }
    function renderHypTree() {
        var root = document.getElementById('hypTreeRoot');
        var badge = document.getElementById('hypCountBadge');
        if (badge) {
            var hn = draft().filter(function(x) { return x.kind === 'hypothesis'; }).length;
            var tn = draft().filter(function(x) { return x.kind === 'task'; }).length;
            badge.textContent = hn + ' гип., ' + tn + ' зад.';
        }
        if (!root) return;
        var a = draft();
        if (!a.filter(function(x) { return x.kind === 'hypothesis'; }).length) {
            root.innerHTML = '<div class="hyp-empty">Гипотез пока нет — нажмите «➕ Добавить гипотезу».</div>';
            return;
        }
        var html = '';
        var hyps = a.filter(function(x) { return x.kind === 'hypothesis'; });
        for (var i = 0; i < hyps.length; i++) {
            var h = hyps[i];
            var kids = a.filter(function(x) { return x.kind === 'task' && x.parent === h.id; });
            var doneCnt = kids.filter(function(x) { return x.status === 'done'; }).length;
            html += '<div class="hyp-card" data-id="' + esc(h.id) + '">'
                + '<div class="hyp-head"><span class="hyp-caret">▼</span>'
                + '<span class="hyp-num">🧪 Гипотеза ' + (h.no || (i + 1)) + '</span>'
                + '<span class="hyp-title-preview">' + esc(h.title || 'без названия') + '</span>'
                + '<span class="hyp-progress">' + doneCnt + '/' + kids.length + '</span>'
                + '<button type="button" class="btn btn-secondary hyp-add-task" style="padding:3px 10px;font-size:.78rem;">➕ Задание</button>'
                + '<button type="button" class="hyp-del-btn" title="Удалить гипотезу и её задания">✕</button>'
                + '</div>'
                + '<div class="hyp-body">' + fieldsHtml(h, false)
                + kids.map(function(t, ti) {
                    return '<div class="hyp-task-block" data-id="' + esc(t.id) + '">'
                        + '<div class="hyp-head"><span class="hyp-title-preview">📌 Задание ' + (ti + 1) + ': ' + esc(t.title || 'без названия') + '</span>'
                        + '<button type="button" class="hyp-del-btn" title="Удалить задание">✕</button></div>'
                        + fieldsHtml(t, true) + '</div>';
                }).join('')
                + '</div></div>';
        }
        root.innerHTML = html;
    }
    window.renderHypTree = renderHypTree;

    // делегирование — переживает перерисовку
    document.addEventListener('click', function(ev) {
        var t = ev.target;
        if (!t) return;
        var addH = t.closest('#hypAddBtn');
        if (addH) { ev.preventDefault(); addHypothesis(); return; }
        var del = t.closest('.hyp-del-btn');
        if (del) {
            ev.preventDefault();
            var blk = del.closest('.hyp-task-block');
            var card = del.closest('.hyp-card');
            if (blk) removeNode(blk.getAttribute('data-id'));
            else if (card) removeNode(card.getAttribute('data-id'));
            return;
        }
        var addT = t.closest('.hyp-add-task');
        if (addT) {
            ev.preventDefault();
            var c = addT.closest('.hyp-card');
            if (c) addTask(c.getAttribute('data-id'));
            return;
        }
        var head = t.closest('.hyp-head');
        if (head && !t.closest('button') && t.tagName !== 'INPUT') {
            var card2 = head.closest('.hyp-card');
            if (card2) card2.classList.toggle('collapsed');
        }
    });
    document.addEventListener('change', function(ev) {
        var t = ev.target;
        if (!t || !t.classList) return;
        if (t.classList.contains('hyp-fld')) {
            var holder = t.closest('[data-id]');
            if (holder) updField(holder.getAttribute('data-id'), t.getAttribute('data-k'), t.value);
            var card = t.closest('.hyp-card');
            if (card) {
                var item = findItem(card.getAttribute('data-id'));
                var pv = card.querySelector('.hyp-title-preview');
                if (item && pv && t.getAttribute('data-k') === 'title') pv.textContent = item.title || 'без названия';
            }
        }
        if (t.type === 'checkbox' && t.closest('.hyp-people-list')) {
            var holder2 = t.closest('[data-id]');
            if (!holder2) return;
            var it = findItem(holder2.getAttribute('data-id'));
            if (!it) return;
            var box = t.closest('.hyp-people-list');
            var picked = [];
            box.querySelectorAll('input[type="checkbox"]:checked').forEach(function(cb) { picked.push(cb.value); });
            it.assignees = picked;
        }
    });
    document.addEventListener('input', function(ev) {
        var t = ev.target;
        if (t && t.classList && t.classList.contains('hyp-fld') && t.tagName === 'TEXTAREA') {
            var holder = t.closest('[data-id]');
            if (holder) updField(holder.getAttribute('data-id'), t.getAttribute('data-k'), t.value);
        }
    });

    // Отключаем устаревший partial-draft экран v1.3.1 (он портил дерево:
    // сохранялся только последний блок).
    try {
        var oldScreen = document.getElementById('hypEditorScreen');
        if (oldScreen && oldScreen.parentNode) oldScreen.parentNode.removeChild(oldScreen);
        var oldStyle = document.getElementById('hyp-editor-style');
        if (oldStyle) oldStyle.remove();
    } catch (e) {}

    var _btn = document.getElementById('hypAddBtn');
    if (_btn) _btn.addEventListener('click', function(e) { e.preventDefault(); addHypothesis(); });
})();
